import { NavLink, Outlet } from "react-router-dom";

const items = [
  { to: "/",          label: "Inicio",    icon: "🏠", end: true },
  { to: "/vehiculos", label: "Vehículos", icon: "🚗" },
  { to: "/espacios",  label: "Espacios",  icon: "🅿️" },
  { to: "/tickets",   label: "Tickets",   icon: "🎫" },
  { to: "/admin", label: "Administración", icon: "⚙️" },
  { to: "/perfil", label: "Mi Perfil", icon: "👤" },
];

function Layout() {
  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "'Segoe UI', sans-serif", background: "#f1f5f9" }}>
      <aside
        style={{
          width: 230,
          background: "#0f172a",
          color: "white",
          padding: "24px 12px",
          display: "flex",
          flexDirection: "column",
          minHeight: "100vh"
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 24, paddingLeft: 8 }}>
          <span style={{ fontSize: 24 }}>🚗</span>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>Estacionamiento</h2>
        </div>
        <nav style={{ display: "flex", flexDirection: "column", gap: 4 }}>
          {items.map(item => (
            <NavLink
              key={item.to}
              to={item.to}
              end={item.end}
              style={({ isActive }) => ({
                display: "flex",
                alignItems: "center",
                gap: 10,
                padding: "12px 16px",
                borderRadius: 8,
                textDecoration: "none",
                fontSize: 15,
                fontWeight: 500,
                background: isActive ? "#1d4ed8" : "transparent",
                color: isActive ? "white" : "#cbd5e1",
              })}
            >
              <span style={{ fontSize: 18 }}>{item.icon}</span>
              {item.label}
            </NavLink>
          ))}
        </nav>
      </aside>
      <main style={{ flex: 1, padding: "32px 28px" }}>
        <Outlet />
      </main>
    </div>
  );
}

export default Layout;
